import{_ as i,o,c as a,ag as c}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-09-21（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-09-21.md","filePath":"topics/biomedicine/science-daily-2026-09-21.md"}'),t={name:"topics/biomedicine/science-daily-2026-09-21.md"};function r(l,e,n,s,d,u){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="科学日报-·-2026-09-21-生物医学" tabindex="-1">科学日报 · 2026-09-21（生物医学） <a class="header-anchor" href="#科学日报-·-2026-09-21-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-09-21（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> — 第28期</p></blockquote><hr><h2 id="无交换的有性生殖-灯心草科以-性-维持克隆式遗传-nature" tabindex="-1">无交换的有性生殖：灯心草科以&quot;性&quot;维持克隆式遗传（Nature） <a class="header-anchor" href="#无交换的有性生殖-灯心草科以-性-维持克隆式遗传-nature" aria-label="Permalink to &quot;无交换的有性生殖：灯心草科以&quot;性&quot;维持克隆式遗传（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> ｜ DOI: 10.1038/s41586-026-11057-7</p></blockquote><ul><li>减数分裂交换通常同时服务两件事：染色体正确分离 + 制造遗传多样性。<em>Rhynchospora tenuis</em>（染色体数最低的有花植物之一）打破了后半句。</li><li>机制：两性减数分裂都是全基因组无交叉（achiasmy）；联会失败，细胞学与遗传上都检测不到交换，中期 I 仍以单价体存在。</li><li>遗传后果：单倍型上转座子不对称积累 → 偏向较大、重复更富染色体的分离扭曲；受精后只有易位兼容配子能结可育种子 → 存活后代与亲本基因型相同。</li><li>洞察：<strong>有性生殖可以在机制上保留、在产物上等价于克隆</strong>。性/克隆不再是非此即彼，而是基因组架构（重组丢失、低染色体数、倒减数分裂、配子兼容选择）组合出来的结果。衔接本主题&quot;中心法则每一环都可被改写&quot;的主线（上期非遗传蛋白变体）。</li></ul><h2 id="crispr-的源头-vipr-用非连续密码做-rna-引导识别-science" tabindex="-1">CRISPR 的源头：VIPR 用非连续密码做 RNA 引导识别（Science） <a class="header-anchor" href="#crispr-的源头-vipr-用非连续密码做-rna-引导识别-science" aria-label="Permalink to &quot;CRISPR 的源头：VIPR 用非连续密码做 RNA 引导识别（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> ｜ DOI: 10.1126/science.aei0498</p></blockquote><ul><li>缺口：CRISPR-Cas 最早的 RNA 引导效应器从哪来，此前没有直接祖先。</li><li>发现：VIPR（Viral Interference Programmable Repeat）——Vipr 蛋白是最早一类 CRISPR-Cas 效应器的祖先；vrRNA 由交替 GGY/NN 组成。</li><li>编码逻辑：不是连续互补配对，而是用可变 NN 二核苷酸集合指定<strong>带空隙的靶序列</strong>，识别双链 DNA。</li><li>功能：自然靶标指向对抗竞争噬菌体；复合物可被重定向做转录抑制，演示可编程噬菌体防御。</li><li>洞察：适应性免疫可能起源于<strong>病毒之间的战争</strong>，而不是细胞一开始就发明了 CRISPR。非连续密码是一种新的序列编码逻辑，可与本库&quot;换机制维度而非优化旧机制&quot;母题互证——识别方式换了维度，而不是把连续互补做得更准。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第28期 科学板块</p></blockquote><p>关键词：achiasmy、减数分裂、克隆生殖、CRISPR、VIPR、vrRNA、噬菌体、适应性免疫、非连续密码 关联：<code>topics/paleoanthropology/</code>（遗传传承与选择）、<code>topics/ai-system-architecture/</code>（编码逻辑/识别机制）</p>',12)])])}const h=i(t,[["render",r]]);export{m as __pageData,h as default};
